namespace BlazorApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 4;

    private readonly List<NotificationItem> _notifications =
    [
        new() { Id = 1, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
        new() { Id = 2, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
        new() { Id = 3, Message = "New feature available: dark mode.", Timestamp = DateTime.UtcNow.AddMinutes(-1) },
    ];

    private static readonly string[] SampleMessages =
    [
        "Deployment completed successfully.",
        "A new user signed up.",
        "Disk usage exceeded 80%.",
        "Backup finished.",
        "Scheduled maintenance at midnight.",
        "New comment on your post.",
    ];

    /// <summary>Returns all notifications available so far.</summary>
    public Task<List<NotificationItem>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public Task<List<NotificationItem>> GetNotificationsSinceAsync(int lastSeenId)
    {
        // Simulate a ~30 % chance of a new notification each poll
        if (Random.Shared.Next(0, 3) == 0)
        {
            lock (_notifications)
            {
                var msg = SampleMessages[Random.Shared.Next(SampleMessages.Length)];
                _notifications.Add(new NotificationItem
                {
                    Id = _nextId++,
                    Message = msg,
                    Timestamp = DateTime.UtcNow,
                });
            }
        }

        lock (_notifications)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > lastSeenId).ToList());
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@inject NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item">
                <strong>@n.Message</strong>
                <small class="text-muted ms-2">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationItem>? notifications;
    private int lastSeenId;
    private CancellationTokenSource? cts;

    [PersistentState]
    public List<NotificationItem>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (PersistedNotifications is not null)
        {
            // Interactive render: state was restored from prerender — skip the fetch
            notifications = PersistedNotifications;
        }
        else
        {
            // Prerender: load from service and persist for the interactive handoff
            notifications = await NotificationSvc.GetNotificationsAsync();
            PersistedNotifications = notifications;
        }

        lastSeenId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Only called in the interactive render — never during prerender
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            await Task.Delay(5000, token);

            var newer = await NotificationSvc.GetNotificationsSinceAsync(lastSeenId);
            if (newer.Count > 0)
            {
                notifications!.AddRange(newer);
                lastSeenId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        cts?.Cancel();
        cts?.Dispose();
    }
}

