namespace BlazorApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 4;

    private readonly List<NotificationItem> _notifications =
    [
        new() { Id = 1, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
        new() { Id = 2, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
        new() { Id = 3, Message = "New feature available: dark mode.", Timestamp = DateTime.UtcNow.AddMinutes(-1) },
    ];

    private static readonly string[] SampleMessages =
    [
        "Deployment completed successfully.",
        "A new user signed up.",
        "Disk usage exceeded 80%.",
        "Backup finished.",
        "Scheduled maintenance at midnight.",
        "New comment on your post.",
    ];

    /// <summary>Returns all notifications available so far.</summary>
    public Task<List<NotificationItem>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public Task<List<NotificationItem>> GetNotificationsSinceAsync(int lastSeenId)
    {
        // Simulate a ~30 % chance of a new notification each poll
        if (Random.Shared.Next(0, 3) == 0)
        {
            lock (_notifications)
            {
                var msg = SampleMessages[Random.Shared.Next(SampleMessages.Length)];
                _notifications.Add(new NotificationItem
                {
                    Id = _nextId++,
                    Message = msg,
                    Timestamp = DateTime.UtcNow,
                });
            }
        }

        lock (_notifications)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > lastSeenId).ToList());
        }
    }
}

